(window.__topouhCourseData??=[]).push({"id":"safety","title":"Основы безопасности жизнедеятельности","lessons":[{"id":"safety-01","title":"Что значит заметить риск","goal":"Отличать обычную ситуацию от той, в которой лучше остановиться и обратиться к взрослому.","source":"Аброськина, Кузнецова, Одновол. «Основы безопасности жизнедеятельности». 2 класс, 2024. с. 5","intro":"На вымышленном рисунке двора одно место огорожено для ремонта, а игровая площадка открыта. Рядом с героями воспитательница.","steps":[{"prompt":"Где герой должен остановиться?","choices":["У свободной скамейки на площадке","Перед ограждением ремонта","У рисунка дерева на стене"],"answer":1,"feedback":["Скамейка не обозначена как опасное место.","Ограждение показывает границу, за которую не заходят.","Обычный рисунок не означает ремонт."]},{"prompt":"Как герой может понять, почему дорожка перекрыта?","choices":["Самому заглянуть за ограждение","Решить, что перегородка для игры","Спросить воспитательницу, не заходя за ограждение"],"answer":2,"feedback":["Смысл ограждения в том, чтобы оставаться снаружи.","Ограждение предупреждает, а не приглашает играть.","Взрослый поможет разобраться безопасно."]},{"prompt":"Что точно указывает, что открытая площадка и участок ремонта различаются?","choices":["Предупреждение и ограждение только у ремонта","Площадка дальше от скамейки","Изображение площадки крупнее"],"answer":0,"feedback":["Это видимые знаки закрытого участка.","Расстояние ничего не говорит о перекрытии.","Размер рисунка не показывает опасность."]},{"prompt":"В другом дворе герою непонятен новый предупреждающий знак. Какой первый шаг подходит?","choices":["Посчитать таблички и пойти дальше","Остановиться и спросить взрослого, которому он доверяет","Угадать значение и никому не говорить"],"answer":1,"feedback":["Число знаков не объясняет предупреждение.","Не нужно сначала проверять риск самому.","В сомнении полезна помощь взрослого."]}],"pass":3},{"id":"safety-02","title":"Маршрут в школу","goal":"Выбирать условный маршрут с тротуаром и обозначенным переходом, а не просто кратчайший.","source":"Аброськина, Кузнецова, Одновол. «Основы безопасности жизнедеятельности». 2 класс, 2024. с. 6, 14","intro":"На придуманной карте длинный путь в школу идёт по тротуару к обозначенному переходу. Короткая тропа обрывается у дороги без перехода.","steps":[{"prompt":"Какой маршрут выбрать герою вместе со взрослым?","choices":["Длинный, с тротуаром и переходом","Короткий, заканчивающийся у дороги","Тот, что на рисунке ярче"],"answer":0,"feedback":["Подходящее место для ходьбы и перехода важнее длины.","На короткой тропе не предусмотрено безопасное место для перехода.","Цвет линии сам по себе не делает путь безопасным."]},{"prompt":"Как найти удобную часть длинного пути?","choices":["Искать подпись «проезжая часть»","Искать подпись «тротуар»","Искать самую толстую линию карты"],"answer":1,"feedback":["Эта часть предназначена для транспорта.","Тротуар обозначает место для пешеходов.","Толщина линии без пояснения не говорит, где идти."]},{"prompt":"Что ещё, кроме тротуара, нужно найти перед пересечением дороги?","choices":["Дерево напротив школы","Самое узкое место на рисунке","Обозначенный пешеходный переход"],"answer":2,"feedback":["Дерево не обозначает переход.","Ширина на картинке не означает, что там можно переходить.","Он показывает место, предназначенное для перехода."]},{"prompt":"На новой карте знакомый тротуар перекрыли. Что лучше выбрать?","choices":["Остановиться и вместе со взрослым найти открытый маршрут","Следовать старой линии на карте, не обращая внимания на перекрытие","Выбрать любую короткую тропу наугад"],"answer":0,"feedback":["Если путь изменился, взрослый поможет выбрать другой безопасный вариант.","Схема не отменяет реальное ограничение.","Короткий путь не обязательно подходит пешеходу."]}],"pass":3},{"id":"safety-03","title":"Светофор и пешеход","goal":"Читать сигнал светофора и не воспринимать зелёный как разрешение бежать не глядя.","source":"Аброськина, Кузнецова, Одновол. «Основы безопасности жизнедеятельности». 2 класс, 2024. с. 30, 35","intro":"В вымышленной сцене герои стоят у перехода с учительницей. Сигналы подписаны словами «красный» и «зелёный».","steps":[{"prompt":"Пешеходам горит «красный». Что делают герои?","choices":["Идут, потому что спешат","Делают шаг вперёд, чтобы проверить сигнал","Остаются ждать рядом с учительницей"],"answer":2,"feedback":["Спешка не меняет значения сигнала.","Проверять сигнал можно, оставаясь на месте.","Красный сигнал означает, что начинать переход нельзя."]},{"prompt":"Появился «зелёный», но машина ещё движется у перехода. Что выбрать?","choices":["Дождаться, когда переход будет свободен, рядом со взрослым","Считать зелёный достаточным и сразу бежать","Идти, глядя только на светофор"],"answer":0,"feedback":["Зелёный сигнал не заменяет проверку обстановки.","Движущаяся машина ещё не освободила переход.","Важно учитывать, что происходит на дороге."]},{"prompt":"Горит «зелёный», переход свободен, взрослый убедился, что можно идти. Как герои идут?","choices":["Наперегонки","Спокойным шагом со взрослым","Отвлекаясь на игру на экране"],"answer":1,"feedback":["Во время гонки труднее замечать обстановку.","Спокойное движение помогает следить за дорогой.","Экран отвлекает внимание от дороги."]},{"prompt":"На новом рисунке один герой сомневается, какой сигнал видит. Как ему поступить?","choices":["Выбрать наугад и пойти","Повторить за бегущим мимо персонажем","Остаться со взрослым и уточнить сигнал"],"answer":2,"feedback":["В этом случае нет уверенности, что переход разрешён.","Действия других не объясняют, какой сигнал горит.","Угадывать при сомнении не нужно."]}],"pass":3},{"id":"safety-04","title":"Личные границы","goal":"Распознавать неудобную просьбу и выбирать обращение к доверенному взрослому.","source":"Аброськина, Кузнецова, Одновол. «Основы безопасности жизнедеятельности». 2 класс, 2024. с. 56","intro":"В вымышленной библиотеке незнакомый персонаж предлагает герою уйти с ним в другое помещение. Рядом работает знакомая учительница.","steps":[{"prompt":"Как герой может ответить?","choices":["Согласиться из вежливости","Отказаться и остаться рядом с учительницей","Передать свои контактные данные вместо ответа"],"answer":1,"feedback":["Вежливость не требует уходить с незнакомым человеком.","Герой не обязан соглашаться на предложение, которое его тревожит.","Личные данные не нужны, чтобы отказаться."]},{"prompt":"Кому лучше рассказать о просьбе?","choices":["Тому, кто просит уйти","Никому, даже если тревожно","Знакомой учительнице"],"answer":2,"feedback":["Именно эта просьба вызвала тревогу.","С тревогой не обязательно оставаться одному.","Это взрослый, которого герой знает и которому доверяет."]},{"prompt":"Если незнакомый персонаж говорит «не рассказывай», что может сделать герой?","choices":["Всё равно обратиться к доверенному взрослому","Считать просьбу обещанием, которое нельзя нарушать","Сначала уйти с персонажем, а потом решить"],"answer":0,"feedback":["Просьба хранить тревожную тайну не отменяет право на помощь.","В тревожной ситуации обратиться за помощью можно.","За помощью лучше обратиться, не уходя с ним."]},{"prompt":"В другой истории знакомый персонаж настойчиво просит сделать то, что пугает героя. Что остаётся верным?","choices":["Знакомым всегда нужно соглашаться помочь","Можно отказаться и рассказать доверенному взрослому","Надо доказать смелость и согласиться"],"answer":1,"feedback":["Знакомство не отменяет право отказаться.","Личные границы важны и со знакомыми людьми.","Смелость может быть в том, чтобы отказаться и позвать на помощь."]}],"pass":3},{"id":"safety-05","title":"Если заметил дым","goal":"Выбирать сообщение взрослому и уход из опасной ситуации без попыток тушить или спасать вещи.","source":"Аброськина, Кузнецова, Одновол. «Основы безопасности жизнедеятельности». 2 класс, 2024. с. 71","intro":"На текстовой карточке из школьного коридора виден дым. Рядом с героями находится учитель.","steps":[{"prompt":"Что лучше сделать, заметив дым?","choices":["Сразу предупредить учителя и вместе уйти из опасной зоны по его указанию","Сначала искать потерянный пенал","Подойти ближе, чтобы получше рассмотреть дым"],"answer":0,"feedback":["Помощь взрослого и уход важнее любых вещей.","Не стоит задерживаться ради вещей.","Приближаться к источнику дыма небезопасно."]},{"prompt":"Пенал остался в комнате, откуда виден дым. Что выбрать?","choices":["Вернуться за пеналом на минутку","Не возвращаться за ним","Попросить другого ребёнка сходить за ним"],"answer":1,"feedback":["Даже короткое возвращение задерживает уход.","В опасной ситуации вещи оставляют.","Не нужно отправлять другого человека в опасное место."]},{"prompt":"Учитель указывает свободное безопасное направление. Что делают герои?","choices":["Остаются посмотреть, исчезнет ли дым сам","Расходятся по одному за своими вещами","Уходят с учителем в указанном направлении"],"answer":2,"feedback":["Ожидание в опасной зоне не помогает.","Важно уйти по указанию, а не возвращаться за вещами.","Взрослый руководит уходом; не нужно искать свой путь без него."]},{"prompt":"В новом сюжете дыма не видит сопровождающий взрослый. Что сделать герою?","choices":["Сразу сказать взрослому и не подходить к дыму","Договориться рассказать позже","Начать самостоятельно разбираться с источником"],"answer":0,"feedback":["Взрослый не всегда видит то же самое; важно сразу предупредить.","Задерживать предупреждение не нужно.","Это не задача ребёнка."]}],"pass":3},{"id":"safety-06","title":"Безопасные решения дома и в школе","goal":"Определять ситуации, где нельзя трогать предмет или где нужна помощь взрослого.","source":"Аброськина, Кузнецова, Одновол. «Основы безопасности жизнедеятельности». 2 класс, 2024. с. 87–92","intro":"На вымышленных карточках дома заметен повреждённый провод, а в школьном проходе разлита жидкость.","steps":[{"prompt":"Что сделать герою, увидев повреждённый провод?","choices":["Потрогать, чтобы проверить повреждение","Переставить его самому","Не трогать и предупредить взрослого"],"answer":2,"feedback":["Проверять повреждённый провод руками опасно.","Провод не нужно двигать самостоятельно.","Взрослому можно сказать о проблеме, оставаясь на расстоянии."]},{"prompt":"Как поступить при пролитой неизвестной жидкости в проходе?","choices":["Остановиться, не наступать и сообщить учителю","Прыгнуть через лужу","Убирать неизвестную жидкость самостоятельно"],"answer":0,"feedback":["Так взрослый сможет помочь и предупредить других.","Рядом с лужей можно поскользнуться.","Сначала взрослый должен разобраться, что произошло."]},{"prompt":"Что общего у обеих карточек?","choices":["Обе проблемы нужно исправить самому","Герой может не трогать опасное место и позвать взрослого","Обе проблемы можно просто скрыть"],"answer":1,"feedback":["Предупредить взрослого важнее самостоятельного исправления.","Это безопасный выбор в обеих историях.","Другим важно узнать о риске."]},{"prompt":"В новой карточке в проходе лежат осколки. Что выбрать?","choices":["Собрать осколки руками","Подвинуть их обувью","Не трогать осколки и предупредить находящегося рядом взрослого"],"answer":2,"feedback":["Об острые края можно пораниться.","Двигать осколки самостоятельно небезопасно.","Поднимать острые осколки ребёнку не нужно."]}],"pass":3},{"id":"safety-07","title":"Двор и вода","goal":"Распознавать места, куда нельзя заходить без взрослого или за обозначенную границу.","source":"Аброськина, Кузнецова, Одновол. «Основы безопасности жизнедеятельности». 2 класс, 2024. с. 96, 101","intro":"На карте вымышленного парка игровая поляна обозначена отдельно от закрытого спуска к воде. С героями гуляет взрослый.","steps":[{"prompt":"Где герои могут выбрать место для игры со взрослым?","choices":["За ограждением спуска","На открытой поляне","На самой кромке воды"],"answer":1,"feedback":["Закрытая граница не подходит для игры.","Она обозначена как игровая зона вдали от закрытого спуска.","У воды нужна особая осторожность и помощь взрослого."]},{"prompt":"Мяч укатился к воде. Как поступить герою?","choices":["В одиночку побежать за мячом","Отправить другого ребёнка","Не приближаться к берегу и сказать взрослому"],"answer":2,"feedback":["Приближаться к воде за мячом небезопасно.","Другого ребёнка тоже нельзя посылать в опасное место.","Мяч не стоит самостоятельного похода к воде."]},{"prompt":"Как понять по карте, что спуск закрыт?","choices":["Есть граница и подпись «проход закрыт»","Поляна нарисована крупнее","Вода нарисована синим"],"answer":0,"feedback":["Текст и ограждение прямо обозначают ограничение.","Размер изображения не объясняет, открыт ли проход.","Цвет воды не показывает, разрешён ли спуск."]},{"prompt":"В новом парке рядом с водой лежит игрушечная лодочка. Что не меняется в правиле?","choices":["За маленькой игрушкой можно идти одному","Остаться на расстоянии и обратиться к взрослому","Если игрушка видна, помощь не нужна"],"answer":1,"feedback":["Размер игрушки не делает берег безопаснее.","Неважно, какая игрушка оказалась у берега.","Видеть игрушку не означает, что подход к ней безопасен."]}],"pass":3},{"id":"safety-08","title":"Здоровые привычки","goal":"Выбирать в вымышленной истории полезные привычки без жёстких норм для всех детей.","source":"Аброськина, Кузнецова, Одновол. «Основы безопасности жизнедеятельности». 2 класс, 2024. с. 109","intro":"В вымышленный свободный день Топа гуляет, играет, перекусывает и оставляет время на отдых.","steps":[{"prompt":"Какая привычка подходит перед перекусом?","choices":["Вымыть руки","Вымыть только свою кружку","Выбрать новую игру вместо мытья рук"],"answer":0,"feedback":["Так меньше грязи попадёт с рук на еду.","Чистая кружка не заменяет мытьё рук.","Смена игры не очищает руки."]},{"prompt":"Топа устал после активной игры. Что поможет отдохнуть?","choices":["Начать новую гонку через силу","Сделать паузу и выбрать спокойное занятие","Остаться без перерыва до вечера"],"answer":1,"feedback":["Более напряжённая игра не заменяет отдыха.","Пауза помогает восстановить силы.","Можно замечать усталость и отдыхать раньше."]},{"prompt":"Какой вымышленный день лучше чередует виды занятий?","choices":["Играть без перерыва весь день","Оставить только одну долгую гонку","Прогулка, обед и спокойный отдых"],"answer":2,"feedback":["Так нет времени на другие нужные занятия.","Это не чередование разных занятий.","Есть движение, еда и пауза."]},{"prompt":"В другом сюжете герой собирается снова рисовать, но уже устал. Что можно перенести из истории Топы?","choices":["Сделать перерыв и вернуться к рисунку после отдыха","Закончить обязательно без паузы","Считать рисунок причиной больше никогда не отдыхать"],"answer":0,"feedback":["Отдых полезен не только после подвижных игр.","Если устал, необязательно принуждать себя продолжать сразу.","Любимое занятие и перерывы могут сочетаться."]}],"pass":3},{"id":"safety-09","title":"Азбука безопасных решений","goal":"Применять правило «остановись и обратись к взрослому» в новой ситуации.","source":"Аброськина, Кузнецова, Одновол. «Основы безопасности жизнедеятельности». 2 класс, 2024. с. 139","intro":"В финале герои разбирают новые текстовые карточки. Ничего из описанного не нужно пробовать в реальности.","steps":[{"prompt":"В кружке герой видит полку, которая накренилась. Что делать ему?","choices":["Держать полку одному","Попросить друга достать предмет с полки","Не подходить и сказать руководителю кружка"],"answer":2,"feedback":["Это опасная задача, которую не нужно решать ребёнку.","Не стоит звать другого ребёнка к опасному месту.","Доверенный взрослый поможет, а герой останется вдали от полки."]},{"prompt":"У входа в спортивный зал герой видит предупреждение, но не понимает его. Что дальше?","choices":["Остаться снаружи и спросить тренера","Войти наугад, чтобы понять знак","Подождать, когда кто-нибудь войдёт, и повторить"],"answer":0,"feedback":["Уточнять назначение знака безопаснее, чем игнорировать его.","Уже сам вход может быть ограничен.","Другой человек может не заметить предупреждение."]},{"prompt":"В библиотеке проход завален неустойчивыми коробками. Что выбрать?","choices":["Протиснуться между коробками","Не проходить и предупредить взрослого сотрудника","Переставить нижнюю коробку"],"answer":1,"feedback":["Неустойчивые коробки могут упасть.","Сотрудник сможет подсказать другой путь и заняться препятствием.","Не нужно самостоятельно двигать неустойчивую стопку."]},{"prompt":"Какое правило пригодилось во всех трёх новых сценах?","choices":["Всегда пробовать решить задачу в одиночку","Действовать как можно быстрее, не глядя вокруг","Остановиться, не проверять риск самому, обратиться к доверенному взрослому"],"answer":2,"feedback":["В незнакомой опасности помощь взрослого уместна.","Спешка не заменяет безопасного решения.","Так можно получить помощь, не приближаясь к опасности."]}],"pass":3},{"id":"safety-10","module":"Закрепление","title":"Остановись и осмотрись","goal":"Замечать простой риск до начала действия.","intro":"Все ситуации нарисованы. Нужно выбрать безопасный следующий шаг, а не пробовать его на улице.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"У прохода в классе стоит коробка, которую трудно обойти. Что разумнее?","choices":["Сообщить учителю и не бежать через тесный проход","Спрятать коробку и никому не сказать","Перепрыгнуть её с разбега"],"answer":0,"feedback":["Взрослый поможет убрать помеху безопасно.","Этот вариант не подходит: «спрятать коробку и никому не сказать». Ещё раз посмотри на условие.","Этот вариант не подходит: «перепрыгнуть её с разбега». Проверь, относится ли выбор к ситуации."]},{"prompt":"На рисунке дети подходят к ограждению ремонта. Что им выбрать?","choices":["Заходить за ограждение по очереди","Остановиться и спросить взрослого, где можно пройти","Снять предупреждающую табличку"],"answer":1,"feedback":["Этот вариант не подходит: «заходить за ограждение по очереди». Ещё раз посмотри на условие.","Ограждение означает, что обычный путь может быть недоступен.","Этот вариант не подходит: «снять предупреждающую табличку». Сравни последствия трёх вариантов."]},{"prompt":"В дворе привычную дорожку перегородили, рядом действует техника. Что делать персонажу?","choices":["Остаться на безопасном месте и позвать взрослого","Быстро пройти между техникой и оградой","Подойти поближе и попросить технику подождать"],"answer":0,"feedback":["Доверенный взрослый поможет подобрать другой путь.","Этот вариант не подходит: «быстро пройти между техникой и оградой». Сравни последствия трёх вариантов.","Этот вариант не подходит: «подойти поближе и попросить технику подождать». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Ребёнок не знает, можно ли ему одному переставлять тяжёлую полку. Как решить?","choices":["Позвать младшего ребёнка, чтобы вдвоём тянуть","Не трогать полку и попросить помощи взрослого","Проверить, потянув её на себя"],"answer":1,"feedback":["Этот вариант не подходит: «позвать младшего ребёнка, чтобы вдвоём тянуть». Проверь, относится ли выбор к ситуации.","Не нужно узнавать вес предмета рискованной попыткой.","Этот вариант не подходит: «проверить, потянув её на себя». Найди объяснение, которое подходит к рисунку."]}],"pass":2},{"id":"safety-11","module":"Закрепление","title":"Маршрут с понятными ориентирами","goal":"На условной карте выбирать путь с безопасными участками.","intro":"На схеме есть тротуар, обозначенный переход и знакомые ориентиры. Настоящий адрес не понадобится.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Какой участок удобнее для пешеходов на рисунке?","choices":["Тротуар вдоль улицы","Полоса между движущимися машинами","Место выезда из-за гаража"],"answer":0,"feedback":["Тротуар позволяет идти отдельным путём, не на проезжей части.","Этот вариант не подходит: «полоса между движущимися машинами». Ещё раз посмотри на условие.","Этот вариант не подходит: «место выезда из-за гаража». Сравни последствия трёх вариантов."]},{"prompt":"Зачем ориентир «библиотека» на вымышленном маршруте?","choices":["Заставляет машины остановиться","Помогает понять, в какой части карты находится переход","Разрешает перейти где угодно"],"answer":1,"feedback":["Этот вариант не подходит: «заставляет машины остановиться». Найди объяснение, которое подходит к рисунку.","Ориентир помогает читать карту, но не заменяет правила безопасности.","Этот вариант не подходит: «разрешает перейти где угодно». Сравни последствия трёх вариантов."]},{"prompt":"Иллюстрация предлагает идти напрямик между припаркованными автомобилями или дойти до обозначенного перехода со взрослым. Какой путь выбрать?","choices":["Между машинами, если так короче","По тротуару к обозначенному переходу со взрослым","По обочине, не обращая внимания на знаки"],"answer":1,"feedback":["Этот вариант не подходит: «между машинами, если так короче». Найди объяснение, которое подходит к рисунку.","Короткий путь не всегда безопаснее; переход лучше заранее увидеть.","Этот вариант не подходит: «по обочине, не обращая внимания на знаки». Проверь, относится ли выбор к ситуации."]},{"prompt":"На схеме путь по тротуару закрыт. Как договориться о новом маршруте?","choices":["Выбрать любую линию с наименьшим числом поворотов","Остановиться и посмотреть со взрослым, где есть другой тротуар","Поменять дорогу самому, не предупреждая"],"answer":1,"feedback":["Этот вариант не подходит: «выбрать любую линию с наименьшим числом поворотов». Ещё раз посмотри на условие.","Маршрут меняют вместе со взрослым, учитывая безопасные ориентиры.","Этот вариант не подходит: «поменять дорогу самому, не предупреждая». Проверь, относится ли выбор к ситуации."]}],"pass":2},{"id":"safety-12","module":"Закрепление","title":"Сигнал и обстановка","goal":"Учитывать светофор и то, что действительно происходит рядом.","intro":"Знак или сигнал помогают решать, но не отменяют внимания к обстановке.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"На светофоре для пешеходов красный, машины стоят. Что выбрать?","choices":["Подождать в безопасном месте","Позвать всех идти за собой","Перейти, пока машины стоят"],"answer":0,"feedback":["Пока сигнал запрещает движение пешеходам, ждут, даже если рядом тихо.","Этот вариант не подходит: «позвать всех идти за собой». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «перейти, пока машины стоят». Сравни последствия трёх вариантов."]},{"prompt":"В вымышленной сцене зелёный, но перед переходом едет машина. Что разумно?","choices":["Стоять прямо на пути машины, чтобы её заметили","Остановиться и со взрослым дождаться безопасной обстановки","Посчитать зелёный сигнал достаточным и побежать"],"answer":1,"feedback":["Этот вариант не подходит: «стоять прямо на пути машины, чтобы её заметили». Проверь, относится ли выбор к ситуации.","Зелёный сигнал не отменяет внимания к движению.","Этот вариант не подходит: «посчитать зелёный сигнал достаточным и побежать». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Компания торопится, а ребёнок на рисунке не видит дорожную обстановку из-за фургона. Какой выбор верный?","choices":["Подождать со взрослым, пока можно безопасно оценить, что происходит","Побежать за первым товарищем","Перейти за фургоном не глядя"],"answer":0,"feedback":["Если обзор закрыт, безопаснее не спешить и попросить взрослого помочь.","Этот вариант не подходит: «побежать за первым товарищем». Ещё раз посмотри на условие.","Этот вариант не подходит: «перейти за фургоном не глядя». Проверь, относится ли выбор к ситуации."]},{"prompt":"Пешеходный светофор не работает, обе полосы оживлены. Что выбрать в истории?","choices":["Идти наугад, если другие дети идут","Считать, что выключенный сигнал всегда разрешает переход","Остановиться в безопасном месте и попросить доверенного взрослого помочь выбрать путь"],"answer":2,"feedback":["Этот вариант не подходит: «идти наугад, если другие дети идут». Ещё раз посмотри на условие.","Этот вариант не подходит: «считать, что выключенный сигнал всегда разрешает переход». Сравни последствия трёх вариантов.","Отсутствие сигнала само по себе не подтверждает безопасность."]}],"pass":2},{"id":"safety-13","module":"Закрепление","title":"Разговор о личных границах","goal":"Отказывать в неудобной просьбе и обращаться за поддержкой.","intro":"Ребёнку не нужно оправдываться или сообщать личные данные. В сценах используются вымышленные имена.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Незнакомый персонаж просит ребёнка уйти с площадки без согласия близких. Что ответить?","choices":["Согласиться из вежливости","Сначала назвать свой адрес","Не идти и обратиться к знакомому взрослому"],"answer":2,"feedback":["Этот вариант не подходит: «согласиться из вежливости». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «сначала назвать свой адрес». Проверь, относится ли выбор к ситуации.","Вежливость не требует соглашаться на то, что тревожит."]},{"prompt":"Кто может помочь, если знакомый человек делает ребёнку неприятное предложение?","choices":["Никто, потому что говорить неудобно","Другой доверенный взрослый, например родитель или учитель","Только тот человек, который это предложил"],"answer":1,"feedback":["Этот вариант не подходит: «никто, потому что говорить неудобно». Ещё раз посмотри на условие.","Можно искать поддержку, даже если просьба исходила от знакомого.","Этот вариант не подходит: «только тот человек, который это предложил». Проверь, относится ли выбор к ситуации."]},{"prompt":"Гость просит сохранить секрет, от которого ребёнку страшно. Что безопаснее?","choices":["Держать тайну, пока никто не спросит","Рассказать доверенному взрослому","Придумать другой страшный секрет"],"answer":1,"feedback":["Этот вариант не подходит: «держать тайну, пока никто не спросит». Ещё раз посмотри на условие.","Тревожный секрет можно и важно обсуждать со взрослым, которому доверяешь.","Этот вариант не подходит: «придумать другой страшный секрет». Сравни последствия трёх вариантов."]},{"prompt":"Кто-то в игре спрашивает, в какой школе учится ребёнок. Как ответить?","choices":["Назвать школу, но не имя","Не сообщать такие данные и обсудить сообщение со взрослым","Отправить расписание и фотографию входа"],"answer":1,"feedback":["Этот вариант не подходит: «назвать школу, но не имя». Сравни последствия трёх вариантов.","Личные сведения не нужны для знакомства в игре.","Этот вариант не подходит: «отправить расписание и фотографию входа». Найди объяснение, которое подходит к рисунку."]}],"pass":2},{"id":"safety-14","module":"Закрепление","title":"Дым: вещи оставляем","goal":"Различать безопасную реакцию и попытку справиться в одиночку.","intro":"В нарисованной истории ребёнок замечает дым. Не нужно разбираться, чем тушить или как брать вещи.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"На рисунке дым, а игрушка осталась рядом. Что выбрать?","choices":["Предупредить взрослого и уйти из опасной зоны по его указанию","Сначала забрать игрушку","Пойти искать, откуда именно дым"],"answer":0,"feedback":["Вещь можно оставить; важно не задерживаться в опасном месте.","Этот вариант не подходит: «сначала забрать игрушку». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «пойти искать, откуда именно дым». Ещё раз посмотри на условие."]},{"prompt":"Ребёнок уже в безопасном месте, но не сказал взрослому о дыме. Что дальше?","choices":["Вернуться и проверить ещё раз","Сразу сообщить доверенному взрослому","Ждать, пока дым заметит кто-то другой"],"answer":1,"feedback":["Этот вариант не подходит: «вернуться и проверить ещё раз». Ещё раз посмотри на условие.","Взрослому нужно узнать об опасности; возвращаться к дыму не надо.","Этот вариант не подходит: «ждать, пока дым заметит кто-то другой». Сравни последствия трёх вариантов."]},{"prompt":"Друг хочет вернуться за рюкзаком в место, где заметил дым. Что ему скажет персонаж?","choices":["Позвать второго ребёнка сходить вместе","Быстро взять рюкзак и побежать","Не возвращаться, предупредить взрослого"],"answer":2,"feedback":["Этот вариант не подходит: «позвать второго ребёнка сходить вместе». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «быстро взять рюкзак и побежать». Сравни последствия трёх вариантов.","Рюкзак не стоит возвращения в опасное место."]},{"prompt":"В школьной вымышленной сцене учитель даёт указания выйти. Как поступить?","choices":["Внимательно слушать и выполнять указания, не задерживаясь за вещами","Выбрать другой путь в одиночку","Вернуться к парте за пеналом"],"answer":0,"feedback":["Согласованные указания взрослого помогают не терять время.","Этот вариант не подходит: «выбрать другой путь в одиночку». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «вернуться к парте за пеналом». Найди объяснение, которое подходит к рисунку."]}],"pass":2},{"id":"safety-15","module":"Закрепление","title":"Предметы и проходы","goal":"Замечать бытовые риски без самостоятельного ремонта.","intro":"В проходах и рядом с незнакомыми предметами полезно остановиться, убрать руки и позвать взрослого.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"На рисунке повреждённый провод возле игровой зоны. Что делать?","choices":["Проверить рукой, нагрелся ли он","Поиграть рядом, ничего не говоря","Не трогать и предупредить взрослого"],"answer":2,"feedback":["Этот вариант не подходит: «проверить рукой, нагрелся ли он». Ещё раз посмотри на условие.","Этот вариант не подходит: «поиграть рядом, ничего не говоря». Сравни последствия трёх вариантов.","Провод не нужно проверять самостоятельно."]},{"prompt":"В школьном коридоре на полу разлита жидкость. Что выбрать?","choices":["Предупредить учителя и не бежать по мокрому полу","Попросить младших детей проверить скользкость","Разгоняться, чтобы проскочить"],"answer":0,"feedback":["Помощь взрослого снижает риск поскользнуться.","Этот вариант не подходит: «попросить младших детей проверить скользкость». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «разгоняться, чтобы проскочить». Сравни последствия трёх вариантов."]},{"prompt":"Герой нашёл дома коробку с неизвестным содержимым. Что дальше?","choices":["Не открывать и спросить доверенного взрослого","Понюхать содержимое, чтобы понять, что это","Переложить содержимое в свою банку"],"answer":0,"feedback":["С неизвестными предметами не надо экспериментировать.","Этот вариант не подходит: «понюхать содержимое, чтобы понять, что это». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «переложить содержимое в свою банку». Проверь, относится ли выбор к ситуации."]},{"prompt":"В классе со стеллажа выступает тяжёлый предмет на высоте. Что сделать?","choices":["Толкнуть стеллаж снизу","Встать на шаткий стул и поправить самому","Не тянуть предмет и позвать взрослого"],"answer":2,"feedback":["Этот вариант не подходит: «толкнуть стеллаж снизу». Ещё раз посмотри на условие.","Этот вариант не подходит: «встать на шаткий стул и поправить самому». Проверь, относится ли выбор к ситуации.","Взрослый оценит обстановку и уберёт риск."]}],"pass":2},{"id":"safety-16","module":"Закрепление","title":"На земле и у воды","goal":"Выбирать безопасную границу игры и просить помощи.","intro":"В заданиях мяч и линия берега нарисованы. Ребёнок не должен подходить к настоящему водоёму ради упражнения.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"На плане игры край площадки проходит далеко от воды. Где играть?","choices":["За ограждением у воды","У самого края воды","В отмеченной зоне вдали от берега под присмотром"],"answer":2,"feedback":["Этот вариант не подходит: «за ограждением у воды». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «у самого края воды». Сравни последствия трёх вариантов.","Условная граница показывает безопасную зону для игры."]},{"prompt":"У вымышленного персонажа мяч катится к воде. Что выбрать?","choices":["Попросить другого ребёнка подбежать первым","Поймать его у самого края","Не идти за мячом, а сказать взрослому"],"answer":2,"feedback":["Этот вариант не подходит: «попросить другого ребёнка подбежать первым». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «поймать его у самого края». Найди объяснение, которое подходит к рисунку.","Мяч можно оставить и обратиться за помощью, оставаясь в безопасном месте."]},{"prompt":"Компания решила пересечь закрытый участок двора ради игры. Что предложить?","choices":["Спрятать ограждение, чтобы не мешало","Играть на закрытом участке, пока никто не видит","Перенести игру на открытую площадку со взрослым"],"answer":2,"feedback":["Этот вариант не подходит: «спрятать ограждение, чтобы не мешало». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «играть на закрытом участке, пока никто не видит». Ещё раз посмотри на условие.","Закрытая зона не подходит для игры даже ненадолго."]},{"prompt":"На картинке знакомый спуск к воде после дождя стал скользким. Как поступить?","choices":["Проверить скользкость, сделав шаг на склон","Сесть и съехать вниз","Остаться вдали от спуска и предупредить взрослого"],"answer":2,"feedback":["Этот вариант не подходит: «проверить скользкость, сделав шаг на склон». Ещё раз посмотри на условие.","Этот вариант не подходит: «сесть и съехать вниз». Сравни последствия трёх вариантов.","Изменившаяся обстановка может сделать привычный путь опасным."]}],"pass":2},{"id":"safety-17","module":"Закрепление","title":"Ритм привычек","goal":"Выбирать полезное действие для конкретной ситуации.","intro":"Отдых, чистые руки и подходящая одежда помогают в разных моментах дня. Не оцениваем внешний вид.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"После игровой площадки герой собирается перекусить. Что добавить?","choices":["Запланировать мытьё на другой день","Вытереть руки о стену","Вымыть руки"],"answer":2,"feedback":["Этот вариант не подходит: «запланировать мытьё на другой день». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «вытереть руки о стену». Найди объяснение, которое подходит к рисунку.","Чистые руки важны перед перекусом."]},{"prompt":"У героя после долгих занятий устали глаза. Что ему выбрать?","choices":["Сделать паузу по договорённости со взрослым","Подвинуть экран вплотную к лицу","Работать дальше без остановки"],"answer":0,"feedback":["Сделать паузу полезнее, чем игнорировать усталость.","Этот вариант не подходит: «подвинуть экран вплотную к лицу». Ещё раз посмотри на условие.","Этот вариант не подходит: «работать дальше без остановки». Проверь, относится ли выбор к ситуации."]},{"prompt":"На рисунке погода резко изменилась, герой замёрз. Как действовать?","choices":["Пойти в незнакомое место в одиночку","Скрыть, что ему холодно","Сообщить взрослому и вместе решить, где согреться"],"answer":2,"feedback":["Этот вариант не подходит: «пойти в незнакомое место в одиночку». Сравни последствия трёх вариантов.","Этот вариант не подходит: «скрыть, что ему холодно». Ещё раз посмотри на условие.","Взрослый поможет выбрать тёплое безопасное место."]},{"prompt":"Герою поручено много дел, и он очень устал. Как сделать план посильным?","choices":["Попросить взрослого помочь распределить дела и отдых","Не говорить об усталости до вечера","Убрать из плана любой отдых"],"answer":0,"feedback":["Перерывы и помощь делают нагрузку посильнее.","Этот вариант не подходит: «не говорить об усталости до вечера». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «убрать из плана любой отдых». Сравни последствия трёх вариантов."]}],"pass":2},{"id":"safety-18","module":"Закрепление","title":"Безопасный следующий шаг","goal":"Разбирать момент, когда нужно остановиться и позвать помощь.","intro":"Не каждое затруднение требует такого же решения. Ясная причина помогает выбрать следующий шаг.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Герой не узнаёт взрослого, который предлагает показать путь. Что предпочтительнее?","choices":["Назвать номер дома для удобства","Сразу идти за новым знакомым","Оставаться в знакомом безопасном месте и обратиться к доверенному взрослому"],"answer":2,"feedback":["Этот вариант не подходит: «назвать номер дома для удобства». Ещё раз посмотри на условие.","Этот вариант не подходит: «сразу идти за новым знакомым». Проверь, относится ли выбор к ситуации.","Безопаснее искать помощь у того, кому персонаж доверяет."]},{"prompt":"Знакомую дверь временно закрыли предупреждающей лентой. Что можно сделать?","choices":["Спросить взрослого, где разрешён проход","Бежать к двери, не глядя","Снять ленту и пройти как раньше"],"answer":0,"feedback":["Предупреждение означает, что обычный путь может измениться.","Этот вариант не подходит: «бежать к двери, не глядя». Сравни последствия трёх вариантов.","Этот вариант не подходит: «снять ленту и пройти как раньше». Ещё раз посмотри на условие."]},{"prompt":"В вымышленной сцене ребёнок видит две опасности: скользкий пол и незнакомый провод. Как выбрать безопасный общий шаг?","choices":["Выбрать одну опасность и промолчать о второй","Сначала проверить провод, потом вытереть пол","Не приближаться, сказать взрослому об обеих"],"answer":2,"feedback":["Этот вариант не подходит: «выбрать одну опасность и промолчать о второй». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «сначала проверить провод, потом вытереть пол». Сравни последствия трёх вариантов.","Сообщить обо всём можно, не трогая ничего."]},{"prompt":"Почему персонаж не обязан проверять риск самостоятельно?","choices":["Риск обязательно исчезнет, если о нём не говорить","Можно остановиться и обратиться к взрослому","Проверять самим всегда быстрее и лучше"],"answer":1,"feedback":["Этот вариант не подходит: «риск обязательно исчезнет, если о нём не говорить». Найди объяснение, которое подходит к рисунку.","Сомнение само по себе повод безопасно попросить помощи.","Этот вариант не подходит: «проверять самим всегда быстрее и лучше». Проверь, относится ли выбор к ситуации."]}],"pass":2},{"id":"safety-19","module":"Применение","title":"Объясни решение на рисунке","goal":"Узнавать опасный участок и объяснять выбор без проверки в реальности.","intro":"Смотрим на воображаемую ситуацию со стороны: что можно заметить из безопасного места?","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"На рисунке рядом с площадкой открыта калитка в зону ремонта. Что выбрать?","choices":["Позвать друзей проверить территорию","Играть только на открытой площадке и сообщить взрослому","Заглянуть за калитку, чтобы узнать причину"],"answer":1,"feedback":["Этот вариант не подходит: «позвать друзей проверить территорию». Сравни последствия трёх вариантов.","Открытая калитка не отменяет ограничений зоны ремонта.","Этот вариант не подходит: «заглянуть за калитку, чтобы узнать причину». Ещё раз посмотри на условие."]},{"prompt":"Незнакомая вещь лежит поперёк знакомой дорожки. Чем лучше помочь?","choices":["Сфотографировать, переступив через неё","Остаться на расстоянии и предупредить взрослого","Отодвинуть её ногой"],"answer":1,"feedback":["Этот вариант не подходит: «сфотографировать, переступив через неё». Найди объяснение, которое подходит к рисунку.","Предупреждать можно из безопасного места.","Этот вариант не подходит: «отодвинуть её ногой». Сравни последствия трёх вариантов."]},{"prompt":"На схеме есть предупреждающая табличка, но запрещённая дорожка заметно короче. Что защищает персонажа?","choices":["Пройти быстро, чтобы не задерживаться","Выбрать другой путь со взрослым","Не читать табличку"],"answer":1,"feedback":["Этот вариант не подходит: «пройти быстро, чтобы не задерживаться». Проверь, относится ли выбор к ситуации.","Короткий путь не оправдывает игнорирование предупреждения.","Этот вариант не подходит: «не читать табличку». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Почему на безопасной карте важны не только расстояния?","choices":["Нужно учитывать препятствия, разделение транспорта и людей и подсказки взрослых","Длина маршрута сообщает точную погоду","Самая короткая линия всегда надёжна"],"answer":0,"feedback":["Безопасность определяется обстановкой и устройством пути.","Этот вариант не подходит: «длина маршрута сообщает точную погоду». Ещё раз посмотри на условие.","Этот вариант не подходит: «самая короткая линия всегда надёжна». Проверь, относится ли выбор к ситуации."]}],"pass":2},{"id":"safety-20","module":"Применение","title":"Выбор пути с обходом","goal":"Перестраивать безопасный маршрут при препятствии.","intro":"Работаем с придумыванием маршрута, не с планом собственного дома.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Перед условной школой перекрыт участок тротуара. Что предложить взрослому?","choices":["Обойти по проезжей полосе","Пройти под ограждающей лентой","Найти другой тротуар и обозначенное место перехода"],"answer":2,"feedback":["Этот вариант не подходит: «обойти по проезжей полосе». Сравни последствия трёх вариантов.","Этот вариант не подходит: «пройти под ограждающей лентой». Найди объяснение, которое подходит к рисунку.","Ищут безопасный обход, а не короткую дорожку любой ценой."]},{"prompt":"На схеме ребёнок хочет идти вдоль парковочных выездов, хотя рядом тротуар. Что лучше?","choices":["Идти задом, пока не будет видна школа","Срезать через парковку между авто","Идти по тротуару со взрослым, обращая внимание на выезды"],"answer":2,"feedback":["Этот вариант не подходит: «идти задом, пока не будет видна школа». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «срезать через парковку между авто». Найди объяснение, которое подходит к рисунку.","Выезды требуют внимания и не заменяют пешеходный маршрут."]},{"prompt":"Два обхода: у первого видна полоса для машин, у второго тротуар, но переход за углом. Что выбрать?","choices":["Делать выбор по длине линии без других признаков","Со взрослым дойти по тротуару до обозначенного перехода","Выбрать автомобильную полосу ради скорости"],"answer":1,"feedback":["Этот вариант не подходит: «делать выбор по длине линии без других признаков». Ещё раз посмотри на условие.","Безопасные элементы маршрута важнее нескольких лишних шагов.","Этот вариант не подходит: «выбрать автомобильную полосу ради скорости». Проверь, относится ли выбор к ситуации."]},{"prompt":"Герой пришёл к месту, где знакомая схема больше не совпадает с обстановкой. Что делать?","choices":["Остановиться и обсудить со взрослым новую ситуацию","Спрятать схему, чтобы взрослый не видел","Идти точно по старой схеме"],"answer":0,"feedback":["Схема помогает, но текущая обстановка важнее.","Этот вариант не подходит: «спрятать схему, чтобы взрослый не видел». Сравни последствия трёх вариантов.","Этот вариант не подходит: «идти точно по старой схеме». Ещё раз посмотри на условие."]}],"pass":2},{"id":"safety-21","module":"Применение","title":"Когда друзья торопят","goal":"Сохранять безопасный выбор даже под давлением группы.","intro":"В сюжете можно сказать «Я подожду» и обратиться за помощью без спора и спешки.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Друг уже побежал через дорогу на красный. Что делает герой?","choices":["Остаётся в безопасном месте и зовёт доверенного взрослого","Бежит следом, чтобы друг не был один","Выбегает на дорогу, чтобы показать несогласие"],"answer":0,"feedback":["Не надо повторять опасное действие; взрослый может помочь.","Этот вариант не подходит: «бежит следом, чтобы друг не был один». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «выбегает на дорогу, чтобы показать несогласие». Проверь, относится ли выбор к ситуации."]},{"prompt":"У зелёного сигнала компания шумит и отвлекает героя. Что полезно сделать?","choices":["Смотреть только на телефон друга","Весь переход обсуждать игру и не смотреть по сторонам","Сосредоточиться на переходе и оценить обстановку со взрослым"],"answer":2,"feedback":["Этот вариант не подходит: «смотреть только на телефон друга». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «весь переход обсуждать игру и не смотреть по сторонам». Ещё раз посмотри на условие.","Внимание нужно направить на то, что происходит вокруг."]},{"prompt":"В вымышленной сцене друзья говорят «машины далеко» при закрытом обзоре. Что ответить?","choices":["«Я побегу первым и потом проверю»","«Я не вижу, что происходит, подожду со взрослым»","«Вы видите, значит смотреть мне не нужно»"],"answer":1,"feedback":["Этот вариант не подходит: ««Я побегу первым и потом проверю»». Ещё раз посмотри на условие.","Каждый может остановиться, если обстановка ему непонятна.","Этот вариант не подходит: ««Вы видите, значит смотреть мне не нужно»». Сравни последствия трёх вариантов."]},{"prompt":"Сигнал понятен, но персонаж заметил автомобиль, который не остановился. Что важнее?","choices":["Догнать друзей любой ценой","Выйти перед машиной, чтобы напомнить о сигнале","Оставаться в безопасном месте и дождаться безопасной обстановки"],"answer":2,"feedback":["Этот вариант не подходит: «догнать друзей любой ценой». Сравни последствия трёх вариантов.","Этот вариант не подходит: «выйти перед машиной, чтобы напомнить о сигнале». Найди объяснение, которое подходит к рисунку.","Видимое движение машины важнее спешки и давления сверстников."]}],"pass":2},{"id":"safety-22","module":"Применение","title":"Как попросить помощи","goal":"Выбирать ясную безопасную фразу, не раскрывая данные незнакомцам.","intro":"В вымышленных сценах просим о конкретной помощи у доверенного взрослого.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Герою неприятно, что его уговаривают сделать то, чего он не хочет. Как сказать?","choices":["«Мне неудобно, подойду к учителю за помощью»","«Я соглашусь, лишь бы никто не спорил»","«Я назову свой адрес и тогда уйду»"],"answer":0,"feedback":["Можно озвучить чувство и обратиться к доверенному взрослому.","Этот вариант не подходит: ««Я соглашусь, лишь бы никто не спорил»». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: ««Я назову свой адрес и тогда уйду»». Ещё раз посмотри на условие."]},{"prompt":"Взрослый не услышал первую просьбу героя. Что делать?","choices":["Обратиться ещё раз или к другому доверенному взрослому","Считать, что помощь запрещена","Попытаться справиться в одиночку любой ценой"],"answer":0,"feedback":["Повторить просьбу допустимо, если нужна поддержка.","Этот вариант не подходит: «считать, что помощь запрещена». Ещё раз посмотри на условие.","Этот вариант не подходит: «попытаться справиться в одиночку любой ценой». Сравни последствия трёх вариантов."]},{"prompt":"Незнакомый собеседник просит фотографию ученика, чтобы «проверить, кто он». Что выбрать?","choices":["Не отправлять фото и обсудить сообщение с доверенным взрослым","Попросить друга отправить своё фото вместо него","Отправить одну фотографию без имени"],"answer":0,"feedback":["Личные фотографии не следует передавать незнакомому собеседнику.","Этот вариант не подходит: «попросить друга отправить своё фото вместо него». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «отправить одну фотографию без имени». Сравни последствия трёх вариантов."]},{"prompt":"Персонажа беспокоит сообщение, в котором просят никому не говорить об игре. Как начать разговор?","choices":["«Я открою ещё одну ссылку и сам разберусь»","«Я ничего никогда не скажу»","«Мне пришло сообщение, и оно меня тревожит. Помоги разобраться»"],"answer":2,"feedback":["Этот вариант не подходит: ««Я открою ещё одну ссылку и сам разберусь»». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: ««Я ничего никогда не скажу»». Найди объяснение, которое подходит к рисунку.","Простое описание тревоги помогает получить поддержку."]}],"pass":2},{"id":"safety-23","module":"Применение","title":"Не возвращайся за вещами","goal":"Переносить правило безопасности на новую сцену с дымом.","intro":"Даже дорогой или любимый предмет не оправдывает возвращение в опасное место.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"На схеме герой с учителем уходит в безопасное место. Там остался телефон. Что делать?","choices":["Продолжить выход, не возвращаясь за телефоном","Вернуться на несколько секунд","Попросить друга забрать его"],"answer":0,"feedback":["Телефон не важнее безопасности человека.","Этот вариант не подходит: «вернуться на несколько секунд». Ещё раз посмотри на условие.","Этот вариант не подходит: «попросить друга забрать его». Сравни последствия трёх вариантов."]},{"prompt":"Ребёнок вышел и встретил доверенного взрослого, который ещё не видел дыма. Что сказать?","choices":["«Всё проверю сам и потом расскажу»","«Ничего не случилось, вернусь позже»","«Там был дым, я не возвращался за вещами»"],"answer":2,"feedback":["Этот вариант не подходит: ««Всё проверю сам и потом расскажу»». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: ««Ничего не случилось, вернусь позже»». Сравни последствия трёх вариантов.","Нужно сообщить о замеченной опасности, не возвращаясь к ней."]},{"prompt":"В условном коридоре две группы. Одна идёт с учителем, другая соревнуется, кто соберёт вещи быстрее. Что выбрать?","choices":["Ждать знакомых рядом с дымом","Быстро собрать вещи и догонять","Идти с учителем и оставлять вещи"],"answer":2,"feedback":["Этот вариант не подходит: «ждать знакомых рядом с дымом». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «быстро собрать вещи и догонять». Найди объяснение, которое подходит к рисунку.","Не задерживайся ради вещей и действуй по указанию взрослого."]},{"prompt":"Герой уже вдали от опасности, но хочет снять дым поближе. Как помочь ему выбрать?","choices":["Вернуться с другим ребёнком","Остаться в безопасном месте со взрослым","Подойти для хорошего кадра"],"answer":1,"feedback":["Этот вариант не подходит: «вернуться с другим ребёнком». Ещё раз посмотри на условие.","Снимок не стоит приближения к опасности.","Этот вариант не подходит: «подойти для хорошего кадра». Проверь, относится ли выбор к ситуации."]}],"pass":2},{"id":"safety-24","module":"Применение","title":"Безопасный порядок в классе","goal":"Организовывать шаги «не трогай, обходи, сообщи», если обнаружена помеха.","intro":"Тренируем решения по картинкам и карточкам. Ничего не чиним и не проверяем.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Как поступить, если в учебном рисунке рядом с дверью стоит неустойчивый высокий предмет?","choices":["Обойти безопасным путём и сказать учителю","Опираясь на предмет, посмотреть за него","Подтянуть к себе, проверяя прочность"],"answer":0,"feedback":["Помехой занимается взрослый.","Этот вариант не подходит: «опираясь на предмет, посмотреть за него». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «подтянуть к себе, проверяя прочность». Сравни последствия трёх вариантов."]},{"prompt":"У персонажа упал маленький карандаш рядом с повреждённым кабелем. Что сначала?","choices":["Тянуться под кабель за карандашом","Отойти и позвать взрослого","Перекладывать кабель ради карандаша"],"answer":1,"feedback":["Этот вариант не подходит: «тянуться под кабель за карандашом». Найди объяснение, которое подходит к рисунку.","Маленькая потеря не оправдывает контакт с повреждённым кабелем.","Этот вариант не подходит: «перекладывать кабель ради карандаша». Проверь, относится ли выбор к ситуации."]},{"prompt":"Скользкое место оказалось сразу за поворотом. Как безопасно предупредить о нём?","choices":["Позвать друзей устроить испытание","Сказать взрослому из безопасного места, где оно находится","Бежать по нему, показывая опасность"],"answer":1,"feedback":["Этот вариант не подходит: «позвать друзей устроить испытание». Ещё раз посмотри на условие.","Об опасности сообщают без демонстрации риска.","Этот вариант не подходит: «бежать по нему, показывая опасность». Проверь, относится ли выбор к ситуации."]},{"prompt":"Почему не надо самостоятельно ставить на место тяжёлый упавший предмет?","choices":["Возможен риск, и нужен взрослый","Тяжёлый предмет всегда держится сам","Предмет понимает только взрослую речь"],"answer":0,"feedback":["Помощь взрослого позволяет оценить задачу и не рисковать.","Этот вариант не подходит: «тяжёлый предмет всегда держится сам». Сравни последствия трёх вариантов.","Этот вариант не подходит: «предмет понимает только взрослую речь». Ещё раз посмотри на условие."]}],"pass":2},{"id":"safety-25","module":"Применение","title":"Игра с безопасными границами","goal":"Переносить игру в безопасную зону при изменении условий.","intro":"Границы игры — часть плана. Когда место стало опасным, игру можно перенести.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"После дождя на условной карте появилась скользкая дорожка к реке. Как изменить игру?","choices":["Выбрать другую площадку со взрослым, вдали от воды","Поставить одного ребёнка проверять её","Включить скользкую дорожку в игру"],"answer":0,"feedback":["Изменившееся место не нужно проверять самостоятельно.","Этот вариант не подходит: «поставить одного ребёнка проверять её». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «включить скользкую дорожку в игру». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Куда лучше положить воображаемую отметку «старт», если мяч часто улетает за границу?","choices":["Дальше от границы и воды","За закрытым ограждением","Рядом с обрывом, чтобы быстрее подбирать мяч"],"answer":0,"feedback":["Быстро подобрать мяч менее важно, чем отдалить игру от опасной зоны.","Этот вариант не подходит: «за закрытым ограждением». Ещё раз посмотри на условие.","Этот вариант не подходит: «рядом с обрывом, чтобы быстрее подбирать мяч». Проверь, относится ли выбор к ситуации."]},{"prompt":"В истории товарищ роняет предмет за ограждение у берега и просит помочь. Что предложить?","choices":["Остаться снаружи и позвать взрослого","Пойти вдвоём за ограждение","Наклониться над водой, не предупредив никого"],"answer":0,"feedback":["Взрослый решает, как поступить, а детям не нужно приближаться к воде.","Этот вариант не подходит: «пойти вдвоём за ограждение». Ещё раз посмотри на условие.","Этот вариант не подходит: «наклониться над водой, не предупредив никого». Сравни последствия трёх вариантов."]},{"prompt":"На рисунке даже разрешённая площадка слишком близко к воде, а рядом нет доверенного взрослого. Как поступить?","choices":["Считать, что знак разрешает любую игру","Выбрать другое место либо дождаться взрослого","Послать младшего проверять край площадки"],"answer":1,"feedback":["Этот вариант не подходит: «считать, что знак разрешает любую игру». Сравни последствия трёх вариантов.","Наличие площадки не отменяет конкретных условий и близости воды.","Этот вариант не подходит: «послать младшего проверять край площадки». Найди объяснение, которое подходит к рисунку."]}],"pass":2},{"id":"safety-26","module":"Применение","title":"Впиши паузу в день","goal":"Применять повседневные здоровые привычки при нагрузке.","intro":"Режим обсуждаем на примере персонажа. Ребёнок может говорить о своём самочувствии без стыда.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Герой долго играет на компьютере. Что добавить в расписание?","choices":["Ещё один час без перерыва","Правило не говорить о том, что устал","Короткую паузу и другое занятие"],"answer":2,"feedback":["Этот вариант не подходит: «ещё один час без перерыва». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «правило не говорить о том, что устал». Ещё раз посмотри на условие.","Перерыв позволяет переключиться и отдохнуть."]},{"prompt":"В вымышленной истории перед обедом руки в краске. Какой шаг выбрать?","choices":["Перенести мытьё на после еды","Быстро вытереть руки о скатерть","Сначала вымыть руки"],"answer":2,"feedback":["Этот вариант не подходит: «перенести мытьё на после еды». Сравни последствия трёх вариантов.","Этот вариант не подходит: «быстро вытереть руки о скатерть». Ещё раз посмотри на условие.","После рисования и до еды руки нужно вымыть."]},{"prompt":"У школьного героя болит голова, а группа хочет идти на игру. Как он может поступить?","choices":["Держать всё в тайне","Поговорить о самочувствии с учителем и попросить паузу","Самостоятельно искать таблетки"],"answer":1,"feedback":["Этот вариант не подходит: «держать всё в тайне». Сравни последствия трёх вариантов.","О плохом самочувствии говорят доверенному взрослому.","Этот вариант не подходит: «самостоятельно искать таблетки». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Почему в длинном плане дня полезно заранее отметить время отдыха?","choices":["Отдых нужен только после победы","Так проще не забыть о паузе, когда много дел","Так все задания станут обязательными без перерывов"],"answer":1,"feedback":["Этот вариант не подходит: «отдых нужен только после победы». Проверь, относится ли выбор к ситуации.","Отдых не требуется заслуживать, его можно планировать.","Этот вариант не подходит: «так все задания станут обязательными без перерывов». Найди объяснение, которое подходит к рисунку."]}],"pass":2},{"id":"safety-27","module":"Применение","title":"Новая сцена: сделай выбор","goal":"Применять безопасные решения в двух незнакомых сценариях.","intro":"На картинке ищем безопасный следующий шаг. Правильность зависит от ситуации, а не от скорости.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"У знакомого магазина идёт ремонт, а указанные стрелки направляют пешеходов в обход. Что сделать?","choices":["Пройти прямо через ремонт","Открыть временную дверь для проверки","Обсудить со взрослым отмеченный безопасный обход"],"answer":2,"feedback":["Этот вариант не подходит: «пройти прямо через ремонт». Ещё раз посмотри на условие.","Этот вариант не подходит: «открыть временную дверь для проверки». Сравни последствия трёх вариантов.","Предупреждения помогают изменить привычный маршрут."]},{"prompt":"Кто-то в онлайн-игре зовёт героя на встречу и спрашивает адрес. Как действовать?","choices":["Сообщить только номер дома","Прийти, но попросить друга молчать","Не сообщать адрес, не идти на встречу и поговорить со взрослым"],"answer":2,"feedback":["Этот вариант не подходит: «сообщить только номер дома». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «прийти, но попросить друга молчать». Сравни последствия трёх вариантов.","За помощью можно обратиться без передачи своих данных незнакомцу."]},{"prompt":"На последней картинке герой замечает дым и слышит предложение «вернись за телефоном». Какое безопасное решение он принимает?","choices":["Задерживается ради телефона","Уходит из опасной зоны по указанию взрослого и не возвращается за вещами","Просит другого ребёнка забрать вещь"],"answer":1,"feedback":["Этот вариант не подходит: «задерживается ради телефона». Найди объяснение, которое подходит к рисунку.","Не надо задерживаться или возвращаться за вещами.","Этот вариант не подходит: «просит другого ребёнка забрать вещь». Проверь, относится ли выбор к ситуации."]},{"prompt":"Нужно закончить сюжет: игрушка упала рядом с повреждённым проводом, а герой стоит в безопасности. Что дальше?","choices":["Дотянуться до игрушки любой ценой","Не трогать провод и сказать взрослому, где это произошло","Переместить провод, чтобы быстро закончить игру"],"answer":1,"feedback":["Этот вариант не подходит: «дотянуться до игрушки любой ценой». Проверь, относится ли выбор к ситуации.","Можно попросить помощи и не менять безопасное положение.","Этот вариант не подходит: «переместить провод, чтобы быстро закончить игру». Ещё раз посмотри на условие."]}],"pass":2}]});
